export const argMaxLatest_entityEnrichment = join({ a: argMaxLatest, c: components }).on(r => r.a.entityId.eq(r.c.entityId)).map(r => ({ ...r.a, matched: r.c.matched_part_ids.length(), updatedAt: r.c.updatedAt }));
export const argMaxLatest_arrayEnrichment = join({ a: argMaxLatest, c: components.arrayJoin(c => c.matched_part_ids, 'partId') }).on(r => r.a.entityId.eq(r.c.entityId)).map(r => ({ ...r.a, partId: r.c.partId }));
export const argMaxLatest_rollupShare = argMaxLatest.groupBy(r => ({ entityId: r.entityId })).aggregate(() => ({ occurrences: count() })).map(r => ({ entityId: r.entityId, occurrences: r.occurrences, proportion: r.occurrences.divide(scalar(argMaxLatest.aggregate(() => count()))) }));
const weekly = availability.final().groupBy(r => ({ entityId: r.entityId, week: r.effectiveAt.toStartOfWeek() })).aggregate(g => ({ mean: avg(g.market_stock_total), median: quantile(0.5)(g.market_lead_time_p50_days) }));
export const weekly_project = weekly.map(r => ({ ...r, labelled: r.entityId.startsWith('cmp_') }));
export const weekly_distinctFilter = weekly.where(r => r.entityId.notEmpty()).distinct();
export const weekly_orderedPage = weekly.orderBy(r => r.entityId.asc()).limit(20, 40);
export const weekly_groupCount = weekly.groupBy(r => ({ entityId: r.entityId })).aggregate(() => ({ occurrences: count() })).where(r => r.occurrences.gt(1n));
export const weekly_semiJoin = weekly.where(r => r.entityId.in(components.where(c => c.state.eq('active')).map(c => c.entityId)));
export const weekly_repeatedUnion = unionAll(weekly, weekly.where(r => r.entityId.startsWith('cmp_'))).distinct();
